schema_ddl:
CREATE TABLE agenzie (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE
);

CREATE TABLE agenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    agenzia_id INT NOT NULL REFERENCES agenzie(id),
    nome TEXT NOT NULL,
    email TEXT NOT NULL
);

CREATE TABLE immobili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    agente_id INT NOT NULL REFERENCES agenti(id),
    titolo TEXT NOT NULL,
    prezzo NUMERIC(12,2) CHECK (prezzo >= 0),
    superficie INT CHECK (superficie > 0)
);

CREATE TABLE visite (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    immobile_id INT NOT NULL REFERENCES immobili(id),
    data_visita TIMESTAMP NOT NULL,
    esito TEXT NOT NULL
);
